  CONSTRAINT fk_candidate_quality_score_recommendation_model_version_id FOREIGN KEY (recommendation_model_version_id) REFERENCES recommendation_model_version (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_candidate_quality_score_candidate_profile_id_current (candidate_profile_id) WHERE is_current,
  INDEX idx_candidate_quality_score_computed_at (computed_at) USING HASH WITH (bucket_count = 16),
  INDEX idx_candidate_quality_score_recommendation_model_version_id (recommendation_model_version_id)
) WITH (ttl_expiration_expression = 'expires_at', ttl_job_cron = '@daily');
