  CONSTRAINT uq_raw_title_normalisation_lang_title UNIQUE (language_id, raw_title_lower),
  CONSTRAINT ck_raw_title_normalisation_confidence_range CHECK (confidence IS NULL OR (confidence >= 0 AND confidence <= 1)),
  CONSTRAINT ck_raw_title_normalisation_review_pair CHECK ((reviewed_at IS NULL) = (reviewed_by_app_user_id IS NULL)),
  CONSTRAINT fk_raw_title_normalisation_language_id FOREIGN KEY (language_id) REFERENCES language (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_raw_title_normalisation_job_role_id FOREIGN KEY (job_role_id) REFERENCES job_role (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_raw_title_normalisation_normalisation_status_id FOREIGN KEY (normalisation_status_id) REFERENCES normalisation_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_raw_title_normalisation_recommendation_model_version_id FOREIGN KEY (recommendation_model_version_id) REFERENCES recommendation_model_version (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_raw_title_normalisation_reviewed_by_app_user_id FOREIGN KEY (reviewed_by_app_user_id) REFERENCES app_user (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  INDEX idx_raw_title_normalisation_normalisation_status_id_seen_count (normalisation_status_id, seen_count DESC),
