  INDEX idx_raw_title_normalisation_job_role_id (job_role_id) WHERE job_role_id IS NOT NULL,
  INDEX idx_raw_title_normalisation_created_at (created_at) USING HASH WITH (bucket_count = 16),
  INDEX idx_raw_title_normalisation_recommendation_model_version_id (recommendation_model_version_id),
  INDEX idx_raw_title_normalisation_reviewed_by_app_user_id (reviewed_by_app_user_id)
);
