  CONSTRAINT fk_recommendation_model_deployment_deployed_by_app_user_id FOREIGN KEY (deployed_by_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_recommendation_model_deployment_recommendation_surface_id_primary_open (recommendation_surface_id) WHERE is_primary AND effective_to IS NULL,
  INDEX idx_recommendation_model_deployment_recommendation_model_version_id_effective_from (recommendation_model_version_id, effective_from DESC),
