  CONSTRAINT ck_search_query_normalised_counts_nonneg CHECK (occurrence_count >= 0 AND zero_result_count >= 0 AND zero_result_count <= occurrence_count),
  CONSTRAINT fk_search_query_normalised_search_scope_id FOREIGN KEY (search_scope_id) REFERENCES search_scope (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
