  CONSTRAINT fk_search_query_normalised_parsed_job_role_id FOREIGN KEY (parsed_job_role_id) REFERENCES job_role (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_search_query_normalised_parsed_skill_id FOREIGN KEY (parsed_skill_id) REFERENCES skill (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_search_query_normalised_parsed_city_id FOREIGN KEY (parsed_city_id) REFERENCES city (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  INVERTED INDEX idx_search_query_normalised_normalised_text (normalised_text gin_trgm_ops),
