  INDEX idx_search_query_normalised_created_at (created_at) USING HASH WITH (bucket_count = 16),
  INDEX idx_search_query_normalised_language_id (language_id),
  INDEX idx_search_query_normalised_parsed_job_role_id (parsed_job_role_id),
  INDEX idx_search_query_normalised_parsed_skill_id (parsed_skill_id),
