  skill_id UUID,
  organisation_id UUID,
  city_id UUID,
  popularity_score INT8 NOT NULL DEFAULT 0,
  is_blocked BOOL NOT NULL DEFAULT false,
  is_active BOOL NOT NULL DEFAULT true,
  CONSTRAINT pk_search_typeahead_term PRIMARY KEY (id),
  CONSTRAINT ck_search_typeahead_term_popularity_nonneg CHECK (popularity_score >= 0),
  CONSTRAINT fk_search_typeahead_term_search_scope_id FOREIGN KEY (search_scope_id) REFERENCES search_scope (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_search_typeahead_term_language_id FOREIGN KEY (language_id) REFERENCES language (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_search_typeahead_term_search_typeahead_kind_id FOREIGN KEY (search_typeahead_kind_id) REFERENCES search_typeahead_kind (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_search_typeahead_term_job_role_id FOREIGN KEY (job_role_id) REFERENCES job_role (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_search_typeahead_term_skill_id FOREIGN KEY (skill_id) REFERENCES skill (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_search_typeahead_term_organisation_id FOREIGN KEY (organisation_id) REFERENCES organisation (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_search_typeahead_term_city_id FOREIGN KEY (city_id) REFERENCES city (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  UNIQUE INDEX uq_search_typeahead_term_search_scope_id_language_term_lower (search_scope_id, language_id, term_lower) WHERE deleted_at IS NULL,
  INVERTED INDEX idx_search_typeahead_term_term_lower_trgm (term_lower gin_trgm_ops),
  INDEX idx_search_typeahead_term_created_at (created_at) USING HASH WITH (bucket_count = 8),
  INDEX idx_search_typeahead_term_search_scope_id_prefix_popular (search_scope_id, term_lower, popularity_score DESC) WHERE is_active AND NOT is_blocked AND deleted_at IS NULL,
  INDEX idx_search_typeahead_term_language_id (language_id),
  INDEX idx_search_typeahead_term_job_role_id (job_role_id),
  INDEX idx_search_typeahead_term_skill_id (skill_id),
  INDEX idx_search_typeahead_term_organisation_id (organisation_id),
  INDEX idx_search_typeahead_term_city_id (city_id)
);
