  CONSTRAINT fk_similar_candidate_recommendation_model_version_id FOREIGN KEY (recommendation_model_version_id) REFERENCES recommendation_model_version (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_similar_candidate_candidate_profile_id_rank_position (candidate_profile_id, rank_position),
  INDEX idx_similar_candidate_computed_at (computed_at) USING HASH WITH (bucket_count = 16),
  INDEX idx_similar_candidate_similar_candidate_profile_id (similar_candidate_profile_id),
  INDEX idx_similar_candidate_recommendation_model_version_id (recommendation_model_version_id)
) WITH (ttl_expiration_expression = 'expires_at', ttl_job_cron = '@daily');
