  risk_decision_id UUID NOT NULL,
  signals JSONB,
  reviewed_by_app_user_id UUID,
  reviewed_at TIMESTAMPTZ,
  scored_at TIMESTAMPTZ NOT NULL,
  is_current BOOL NOT NULL DEFAULT true,
  CONSTRAINT pk_content_risk_score PRIMARY KEY (id),
  CONSTRAINT ck_content_risk_score_risk_score_range CHECK (risk_score >= 0 AND risk_score <= 1),
  CONSTRAINT ck_content_risk_score_one_subject CHECK ((CASE WHEN job_requirement_id IS NOT NULL THEN 1 ELSE 0 END)+(CASE WHEN candidate_profile_id IS NOT NULL THEN 1 ELSE 0 END)+(CASE WHEN organisation_id IS NOT NULL THEN 1 ELSE 0 END) = 1),
  CONSTRAINT ck_content_risk_score_review_pair CHECK ((reviewed_at IS NULL) = (reviewed_by_app_user_id IS NULL)),
  CONSTRAINT fk_content_risk_score_risk_kind_id FOREIGN KEY (risk_kind_id) REFERENCES risk_kind (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_content_risk_score_job_requirement_id FOREIGN KEY (job_requirement_id) REFERENCES job_requirement (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_content_risk_score_candidate_profile_id FOREIGN KEY (candidate_profile_id) REFERENCES candidate_profile (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_content_risk_score_organisation_id FOREIGN KEY (organisation_id) REFERENCES organisation (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_content_risk_score_recommendation_model_version_id FOREIGN KEY (recommendation_model_version_id) REFERENCES recommendation_model_version (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_content_risk_score_risk_decision_id FOREIGN KEY (risk_decision_id) REFERENCES risk_decision (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_content_risk_score_reviewed_by_app_user_id FOREIGN KEY (reviewed_by_app_user_id) REFERENCES app_user (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  INDEX idx_content_risk_score_scored_at_current (scored_at) USING HASH WITH (bucket_count = 8) WHERE is_current,
  UNIQUE INDEX uq_content_risk_score_job_requirement_id_kind_current (job_requirement_id, risk_kind_id) WHERE is_current AND job_requirement_id IS NOT NULL,
  UNIQUE INDEX uq_content_risk_score_candidate_profile_id_kind_current (candidate_profile_id, risk_kind_id) WHERE is_current AND candidate_profile_id IS NOT NULL,
  UNIQUE INDEX uq_content_risk_score_organisation_id_kind_current (organisation_id, risk_kind_id) WHERE is_current AND organisation_id IS NOT NULL,
  INDEX idx_content_risk_score_recommendation_model_version_id (recommendation_model_version_id),
  INDEX idx_content_risk_score_reviewed_by_app_user_id (reviewed_by_app_user_id)
);
