  recommendation_model_version_id UUID NOT NULL,
  ab_variant_id UUID,
  job_requirement_id UUID,
  candidate_profile_id UUID,
  rank_position INT2 NOT NULL,
  request_ref STRING(64) NOT NULL,
  recommendation_click_kind_id UUID NOT NULL,
  clicked_at TIMESTAMPTZ NOT NULL,
  dwell_ms INT4,
  event_ref STRING(64) NOT NULL,
  CONSTRAINT pk_recommendation_click_event PRIMARY KEY (id),
  CONSTRAINT uq_recommendation_click_event_event_ref UNIQUE (event_ref),
  CONSTRAINT ck_recommendation_click_event_one_subject CHECK (job_requirement_id IS NOT NULL OR candidate_profile_id IS NOT NULL),
  CONSTRAINT ck_recommendation_click_event_actor_present CHECK (app_user_id IS NOT NULL OR visitor_ref IS NOT NULL),
  CONSTRAINT ck_recommendation_click_event_dwell_nonneg CHECK (dwell_ms IS NULL OR dwell_ms >= 0),
  CONSTRAINT fk_recommendation_click_event_app_user_id FOREIGN KEY (app_user_id) REFERENCES app_user (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_recommendation_click_event_recommendation_surface_id FOREIGN KEY (recommendation_surface_id) REFERENCES recommendation_surface (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_recommendation_click_event_recommendation_model_version_id FOREIGN KEY (recommendation_model_version_id) REFERENCES recommendation_model_version (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_recommendation_click_event_ab_variant_id FOREIGN KEY (ab_variant_id) REFERENCES ab_variant (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_recommendation_click_event_job_requirement_id FOREIGN KEY (job_requirement_id) REFERENCES job_requirement (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_recommendation_click_event_candidate_profile_id FOREIGN KEY (candidate_profile_id) REFERENCES candidate_profile (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_recommendation_click_event_recommendation_click_kind_id FOREIGN KEY (recommendation_click_kind_id) REFERENCES recommendation_click_kind (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_recommendation_click_event_clicked_at (clicked_at) USING HASH WITH (bucket_count = 32),
  INDEX idx_recommendation_click_event_job_requirement_id_clicked_at (job_requirement_id, clicked_at) USING HASH WITH (bucket_count = 16) WHERE job_requirement_id IS NOT NULL,
  INDEX idx_recommendation_click_event_request_ref_rank_position (request_ref, rank_position),
  INDEX idx_recommendation_click_event_app_user_id (app_user_id),
  INDEX idx_recommendation_click_event_recommendation_model_version_id (recommendation_model_version_id),
  INDEX idx_recommendation_click_event_ab_variant_id (ab_variant_id),
  INDEX idx_recommendation_click_event_candidate_profile_id (candidate_profile_id)
) WITH (ttl_expiration_expression = '(created_at + INTERVAL ''180 days'')', ttl_job_cron = '@daily');
-- @@
CREATE TABLE IF NOT EXISTS recommendation_feedback (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  app_user_id UUID NOT NULL,
  job_requirement_id UUID,
  candidate_profile_id UUID,
  organisation_id UUID,
  recommendation_feedback_kind_id UUID NOT NULL,
  not_interested_reason_id UUID,
  recommendation_surface_id UUID NOT NULL,
  recommendation_model_version_id UUID,
  request_ref STRING(64),
  comment_text STRING(500),
  feedback_at TIMESTAMPTZ NOT NULL,
  CONSTRAINT pk_recommendation_feedback PRIMARY KEY (id),
  CONSTRAINT ck_recommendation_feedback_has_target CHECK (job_requirement_id IS NOT NULL OR candidate_profile_id IS NOT NULL OR organisation_id IS NOT NULL),
  CONSTRAINT fk_recommendation_feedback_app_user_id FOREIGN KEY (app_user_id) REFERENCES app_user (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_recommendation_feedback_job_requirement_id FOREIGN KEY (job_requirement_id) REFERENCES job_requirement (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_recommendation_feedback_candidate_profile_id FOREIGN KEY (candidate_profile_id) REFERENCES candidate_profile (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_recommendation_feedback_organisation_id FOREIGN KEY (organisation_id) REFERENCES organisation (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_recommendation_feedback_recommendation_feedback_kind_id FOREIGN KEY (recommendation_feedback_kind_id) REFERENCES recommendation_feedback_kind (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_recommendation_feedback_not_interested_reason_id FOREIGN KEY (not_interested_reason_id) REFERENCES not_interested_reason (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_recommendation_feedback_recommendation_surface_id FOREIGN KEY (recommendation_surface_id) REFERENCES recommendation_surface (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_recommendation_feedback_recommendation_model_version_id FOREIGN KEY (recommendation_model_version_id) REFERENCES recommendation_model_version (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  INDEX idx_recommendation_feedback_app_user_id_feedback_at (app_user_id, feedback_at DESC),
  INDEX idx_recommendation_feedback_job_requirement_id_feedback_at (job_requirement_id, feedback_at) WHERE job_requirement_id IS NOT NULL,
  INDEX idx_recommendation_feedback_feedback_at (feedback_at) USING HASH WITH (bucket_count = 16),
  INDEX idx_recommendation_feedback_candidate_profile_id (candidate_profile_id),
  INDEX idx_recommendation_feedback_organisation_id (organisation_id),
  INDEX idx_recommendation_feedback_recommendation_model_version_id (recommendation_model_version_id)
) WITH (ttl_expiration_expression = '(created_at + INTERVAL ''730 days'')', ttl_job_cron = '@daily');
-- @@
CREATE TABLE IF NOT EXISTS recommendation_impression (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  app_user_id UUID,
  visitor_ref STRING(64),
  recommendation_surface_id UUID NOT NULL,
  recommendation_model_version_id UUID NOT NULL,
  ab_variant_id UUID,
  job_requirement_id UUID,
  candidate_profile_id UUID,
  rank_position INT2 NOT NULL,
  request_ref STRING(64) NOT NULL,
  impressed_at TIMESTAMPTZ NOT NULL,
  is_viewable BOOL NOT NULL DEFAULT false,
  CONSTRAINT pk_recommendation_impression PRIMARY KEY (id),
  CONSTRAINT uq_recommendation_impression_request_position UNIQUE (request_ref, rank_position),
  CONSTRAINT ck_recommendation_impression_one_subject CHECK (job_requirement_id IS NOT NULL OR candidate_profile_id IS NOT NULL),
  CONSTRAINT ck_recommendation_impression_actor_present CHECK (app_user_id IS NOT NULL OR visitor_ref IS NOT NULL),
  CONSTRAINT fk_recommendation_impression_app_user_id FOREIGN KEY (app_user_id) REFERENCES app_user (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_recommendation_impression_recommendation_surface_id FOREIGN KEY (recommendation_surface_id) REFERENCES recommendation_surface (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_recommendation_impression_recommendation_model_version_id FOREIGN KEY (recommendation_model_version_id) REFERENCES recommendation_model_version (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_recommendation_impression_ab_variant_id FOREIGN KEY (ab_variant_id) REFERENCES ab_variant (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_recommendation_impression_job_requirement_id FOREIGN KEY (job_requirement_id) REFERENCES job_requirement (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_recommendation_impression_candidate_profile_id FOREIGN KEY (candidate_profile_id) REFERENCES candidate_profile (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  INDEX idx_recommendation_impression_impressed_at (impressed_at) USING HASH WITH (bucket_count = 32),
  INDEX idx_recommendation_impression_job_requirement_id_impressed_at (job_requirement_id, impressed_at) USING HASH WITH (bucket_count = 16) WHERE job_requirement_id IS NOT NULL,
  INDEX idx_recommendation_impression_app_user_id_impressed_at (app_user_id, impressed_at DESC) WHERE app_user_id IS NOT NULL,
  INDEX idx_recommendation_impression_recommendation_model_version_id (recommendation_model_version_id),
  INDEX idx_recommendation_impression_ab_variant_id (ab_variant_id),
  INDEX idx_recommendation_impression_candidate_profile_id (candidate_profile_id)
) WITH (ttl_expiration_expression = '(created_at + INTERVAL ''90 days'')', ttl_job_cron = '@daily');
-- @@
CREATE TABLE IF NOT EXISTS salary_prediction (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  job_requirement_id UUID,
  candidate_profile_id UUID,
  job_role_id UUID,
  country_id UUID NOT NULL,
  city_id UUID,
  predicted_min DECIMAL(18,4) NOT NULL,
  predicted_median DECIMAL(18,4) NOT NULL,
  predicted_max DECIMAL(18,4) NOT NULL,
  currency_id UUID NOT NULL,
  salary_period_id UUID NOT NULL,
  confidence DECIMAL(5,4) NOT NULL,
  sample_size INT4 NOT NULL,
  recommendation_model_version_id UUID NOT NULL,
  predicted_at TIMESTAMPTZ NOT NULL,
  is_current BOOL NOT NULL DEFAULT true,
  CONSTRAINT pk_salary_prediction PRIMARY KEY (id),
  CONSTRAINT ck_salary_prediction_one_subject CHECK ((job_requirement_id IS NULL) <> (candidate_profile_id IS NULL)),
  CONSTRAINT ck_salary_prediction_range_order CHECK (predicted_min >= 0 AND predicted_min <= predicted_median AND predicted_median <= predicted_max),
  CONSTRAINT ck_salary_prediction_confidence_range CHECK (confidence >= 0 AND confidence <= 1),
  CONSTRAINT ck_salary_prediction_sample_nonneg CHECK (sample_size >= 0),
  CONSTRAINT fk_salary_prediction_job_requirement_id FOREIGN KEY (job_requirement_id) REFERENCES job_requirement (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_salary_prediction_candidate_profile_id FOREIGN KEY (candidate_profile_id) REFERENCES candidate_profile (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_salary_prediction_job_role_id FOREIGN KEY (job_role_id) REFERENCES job_role (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_salary_prediction_country_id FOREIGN KEY (country_id) REFERENCES country (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_salary_prediction_city_id FOREIGN KEY (city_id) REFERENCES city (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_salary_prediction_currency_id FOREIGN KEY (currency_id) REFERENCES currency (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_salary_prediction_salary_period_id FOREIGN KEY (salary_period_id) REFERENCES salary_period (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_salary_prediction_recommendation_model_version_id FOREIGN KEY (recommendation_model_version_id) REFERENCES recommendation_model_version (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_salary_prediction_job_requirement_id_current (job_requirement_id) WHERE is_current AND job_requirement_id IS NOT NULL,
  UNIQUE INDEX uq_salary_prediction_candidate_profile_id_current (candidate_profile_id) WHERE is_current AND candidate_profile_id IS NOT NULL,
  INDEX idx_salary_prediction_predicted_at (predicted_at) USING HASH WITH (bucket_count = 16),
  INDEX idx_salary_prediction_job_role_id (job_role_id),
  INDEX idx_salary_prediction_country_id (country_id),
  INDEX idx_salary_prediction_city_id (city_id),
  INDEX idx_salary_prediction_currency_id (currency_id),
  INDEX idx_salary_prediction_recommendation_model_version_id (recommendation_model_version_id)
);
-- @@
CREATE TABLE IF NOT EXISTS similar_job (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  job_requirement_id UUID NOT NULL,
  similar_job_requirement_id UUID NOT NULL,
  similarity_method_id UUID NOT NULL,
  similarity_score DECIMAL(7,6) NOT NULL,
  rank_position INT2 NOT NULL,
  recommendation_model_version_id UUID,
  computed_at TIMESTAMPTZ NOT NULL,
  expires_at TIMESTAMPTZ NOT NULL,
  CONSTRAINT pk_similar_job PRIMARY KEY (id),
  CONSTRAINT uq_similar_job_edge UNIQUE (job_requirement_id, similar_job_requirement_id, similarity_method_id),
  CONSTRAINT ck_similar_job_not_self CHECK (job_requirement_id <> similar_job_requirement_id),
  CONSTRAINT ck_similar_job_similarity_score_range CHECK (similarity_score >= 0 AND similarity_score <= 1),
  CONSTRAINT ck_similar_job_rank_positive CHECK (rank_position >= 1),
  CONSTRAINT fk_similar_job_job_requirement_id FOREIGN KEY (job_requirement_id) REFERENCES job_requirement (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_similar_job_similar_job_requirement_id FOREIGN KEY (similar_job_requirement_id) REFERENCES job_requirement (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_similar_job_similarity_method_id FOREIGN KEY (similarity_method_id) REFERENCES similarity_method (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_similar_job_recommendation_model_version_id FOREIGN KEY (recommendation_model_version_id) REFERENCES recommendation_model_version (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_similar_job_job_requirement_id_rank_position (job_requirement_id, rank_position),
  INDEX idx_similar_job_computed_at (computed_at) USING HASH WITH (bucket_count = 16),
  INDEX idx_similar_job_similar_job_requirement_id (similar_job_requirement_id),
  INDEX idx_similar_job_recommendation_model_version_id (recommendation_model_version_id)
) WITH (ttl_expiration_expression = 'expires_at', ttl_job_cron = '@daily');
